const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let places=[],foods=[],lunch=[],pizza=[],page='home',filters={};const price=x=>{let n=String(x||'').replace(/\s/g,'').replace(/[^\d,.-]/g,'').replace(',','.');return Number(n)||null},ft=x=>price(x)?new Intl.NumberFormat('hu-HU').format(price(x))+' Ft':'Ár nem ismert',link=x=>/^https?:\/\//i.test(x||'')?`<a href="${esc(x)}" target="_blank" rel="noopener">Forrás megnyitása ↗</a>`:'',date=x=>x?esc(x):'nem ismert';function cat(x){let s=(x||'').toLowerCase();if(s.includes('leves'))return'Leves';if(s.includes('desszert'))return'Desszert';if(s.includes('főétel'))return'Főétel';return x||'Egyéb'}function filteredFoods(){return foods.filter(x=>x[0]&&x[5]&&!/pizza|pinsa/i.test((x[4]||'')+' '+(x[5]||'')))}function status(p){let n=foods.filter(x=>x[1]===p[0]&&x[5]).length;if(n)return['Már megnéztük az étlapját',n];if(p[0]==='E01')return['Saját étterem',0];if(/feldolgozva|rekord kész/i.test(p[7]||''))return['Van néhány adatunk, de még hiányos',0];return['Még megnézzük / ellenőrizni kell',0]};function go(p){page=p;render();window.scrollTo(0,0)}window.go=go;function title(k,h,p){return `<div class="eyebrow">${k}</div><h1>${h}</h1><p class="subtitle">${p}</p>`}function home(){let ids=new Set(foods.filter(x=>x[1]&&x[5]).map(x=>x[1]));return `<section class="hero"><div class="eyebrow">ELEFÁNT · PIACKUTATÁS</div><h1>Jó döntések<br>egy új étlaphoz.</h1><p>Nézzétek meg, mit kínálnak a környék éttermei, milyen árakkal dolgoznak, és mely helyeket érdemes még megvizsgálnunk.</p><div class="date">KUTATÁSI PILLANATKÉP · 2026. NOVEMBER 9.</div></section><div class="stats"><div class="stat"><strong>${places.length}</strong><span>hely az éttermi listán, az Elefánttal együtt</span></div><div class="stat"><strong>${ids.size}</strong><span>étteremhez találtunk részletes étlapadatot</span></div><div class="stat"><strong>${foods.filter(x=>x[0]&&x[5]).length}</strong><span>rögzített étlapsor · változatokkal együtt</span></div><div class="stat"><strong>11. 09.</strong><span>az adatok utolsó betöltése, 2026</span></div></div><section class="section"><div class="section-head"><div><div class="eyebrow">INDULJUNK EL</div><h2>Mit néznétek meg?</h2></div><p>Válasszatok egy témát, és indulhat a felfedezés.</p></div><div class="tiles">${[['places','⌂','Éttermek a környéken','Kit néztünk már meg, és kiket érdemes még?'],['foods','✳','Ételek és inspiráció','Fogások, alapanyagok és ötletek egy helyen.'],['prices','◌','Árak összehasonlítása','Levesek, főételek, desszertek és ebédmenük.'],['future','↗','Merre tovább?','Mit tudunk most, és mire lehet képes később?']].map(t=>`<button class="tile" onclick="go('${t[0]}')"><i class="icon">${t[1]}</i><strong>${t[2]}</strong><span>${t[3]}</span><b>Felfedezem →</b></button>`).join('')}</div></section><div class="section note"><b>Egy közös munka kezdete.</b> A gyűjtés nem teljes körű, egyes étlapok régebbiek lehetnek. A dátumokat és forrásokat mindenhol megtaláljátok.</div>`}function placelist(){let q=(filters.q||'').toLowerCase(),city=filters.city||'',st=filters.st||'';let arr=places.filter(p=>((p[1]||'')+' '+(p[2]||'')).toLowerCase().includes(q)&&(!city||(city==='Veszprém'?p[2]==='Veszprém':p[2]!=='Veszprém'))&&(!st||(st==='van'?status(p)[1]>0:status(p)[1]===0)));return `${title('KUTATÁSI TÉRKÉP','Kiket néztünk meg?','Nézzétek át a helyeket, és beszéljük meg, kik a legfontosabbak az Elefánt számára.')}<div class="banner"><b>Találkozóhoz:</b> Melyik 5–10 hely jut eszetekbe először? Miért fontosak: a vendégkörük, az áraik, az ételeik vagy a helyszínük miatt? A döntéseket Kitti a forrástáblában rögzíti.</div><div class="toolbar"><input id="q" placeholder="Étterem vagy település keresése" value="${esc(filters.q||'')}"><select id="city"><option value="">Minden település</option><option ${city==='Veszprém'?'selected':''}>Veszprém</option><option value="más" ${city==='más'?'selected':''}>Környező települések</option></select><select id="st"><option value="">Minden kutatási állapot</option><option value="van" ${st==='van'?'selected':''}>Van étlapadat</option><option value="nincs" ${st==='nincs'?'selected':''}>További kutatás szükséges</option></select></div><div class="count">${arr.length} hely a listában</div><div class="cards">${arr.map(p=>{let [s,n]=status(p);return `<article class="card"><span class="tag ${!n?'pending':''}">${s}</span><h3>${esc(p[1])}</h3><p>${esc(p[2])} ${p[4]?' · '+esc(p[4]):''}</p><p>${esc(p[22]||p[11]||'A következő kutatási feladat még egyeztetendő.')}</p><span class="small">Ellenőrzés: ${date(p[12])}${n?' · '+n+' rögzített étlapsor':''}</span><div class="priority"><strong>Mennyire fontos számotokra?</strong>Nagyon fontos · Érdekes lehet · Most nem fontos · Még nem tudjuk</div>${n?`<a href="#" onclick="filters={restaurant:'${esc(p[0])}'};go('foods');return false">Ételek megnézése →</a>`:''}${link(p[6])}</article>`}).join('')}</div>`}function foodlist(){let q=(filters.q||'').toLowerCase(),rest=filters.restaurant||'',category=filters.category||'',max=Number(filters.max||0);let arr=filteredFoods().filter(x=>((x[5]||'')+' '+(x[6]||'')+' '+(x[2]||'')).toLowerCase().includes(q)&&(!rest||x[1]===rest)&&(!category||cat(x[4])===category)&&(!max||(price(x[7])&&price(x[7])<=max)));let cats=[...new Set(filteredFoods().map(x=>cat(x[4])))].filter(Boolean).sort((a,b)=>a.localeCompare(b,'hu'));return `${title('ÉTLAPBÖNGÉSZŐ','Ételek és inspiráció','Keressetek fogást, alapanyagot vagy éttermet a már feldolgozott étlapokban.')}<div class="toolbar"><input id="q" placeholder="Például: kacsa, leves, desszert" value="${esc(filters.q||'')}"><select id="restaurant"><option value="">Minden étterem</option>${places.filter(p=>foods.some(x=>x[1]===p[0]&&x[5])).map(p=>`<option value="${esc(p[0])}" ${rest===p[0]?'selected':''}>${esc(p[1])}</option>`).join('')}</select><select id="category"><option value="">Minden ételtípus</option>${cats.map(c=>`<option ${c===category?'selected':''}>${esc(c)}</option>`).join('')}</select><input id="max" type="number" min="0" placeholder="Legfeljebb Ft" value="${esc(filters.max||'')}"></div><div class="count">${arr.length} találat · a változatok külön sorban szerepelhetnek</div><div class="cards">${arr.slice(0,90).map(x=>`<article class="card"><span class="tag">${esc(x[4]||'Fogás')}</span><h3>${esc(x[5])}</h3><p>${esc(x[2])} · ${esc(x[3])}</p>${x[6]?`<p>${esc(x[6])}</p>`:''}<div class="price">${ft(x[7])}</div><p>${x[32]?'Köret: '+esc(x[32]):'Köret: nem ismert'} · ${x[12]?esc(x[12]):'Csatorna: nem ismert'}</p><span class="small">Ár ellenőrizve: ${date(x[15])} · Érvényesség: ${x[13]?date(x[13]):'nem ismert'}</span>${x[21]?`<p>${esc(x[21])}</p>`:''}${link(x[16])}</article>`).join('')}</div>${!arr.length?'<div class="note">Erre most nem találtunk fogást. Próbáljatok másik alapanyagot vagy tágabb keresést.</div>':''}${arr.length>90?`<div class="note">Az első 90 találat látható. Szűkítsétek a keresést a többiekhez.</div>`:''}`}
function prices(){let tab=filters.tab||'Leves';let opts=['Leves','Főétel','Desszert','Kétfogásos ebédmenü'];let rows=tab==='Kétfogásos ebédmenü'?lunch.filter(x=>String(x[5])==='2'):filteredFoods().filter(x=>cat(x[4])===tab&&x[28]==='Önálló fogás'&&price(x[7]));return `${title('ÖSSZEHASONLÍTÁS','Milyen árakkal dolgoznak?','Nézzétek meg a konkrét fogásokat és ajánlatokat. Az árak különböző időpontokból származhatnak.')}<div class="tabs">${opts.map(o=>`<button class="${tab===o?'on':''}" onclick="filters.tab='${o}';render()">${o}</button>`).join('')}</div><div class="note"><b>Fontos:</b> A kiírt árak alapján látható példák nem feltétlenül azonos adagokra vagy aktuális étlapra vonatkoznak. A szervizdíj és a csatorna helyenként eltérhet.</div><div class="count">${rows.length} rögzített ${tab==='Kétfogásos ebédmenü'?'ajánlat':'étlapsor'} · ${new Set(rows.map(x=>x[1])).size} hely</div><div class="cards">${rows.map(x=>tab==='Kétfogásos ebédmenü'?`<article class="card"><span class="tag">KÉTFOGÁSOS EBÉDMENÜ</span><h3>${esc(x[2])}</h3><p>${esc(x[3])} · ${esc(x[6]||'Csatorna nem ismert')}</p><div class="price">${ft(x[7])}</div><p>Szervizdíj: ${esc(x[8]||'nem ismert')}${x[10]?' · vele számítva '+ft(x[10]):''}</p><span class="small">Ajánlat: ${date(x[13])} – ${date(x[14])} · Ellenőrzés: ${date(x[15])}</span><p>${esc(x[19]||'')}</p>${link(x[16])}</article>`:`<article class="card"><span class="tag">${esc(x[4])}</span><h3>${esc(x[5])}</h3><p>${esc(x[2])} · ${esc(x[3])}</p><div class="price">${ft(x[7])}</div><p>Szervizdíj: ${esc(x[9]||'nem ismert')}${x[11]?' · vele számítva '+ft(x[11]):''}</p><p>${esc(x[12]||'Csatorna nem ismert')} ${x[32]?' · Köret: '+esc(x[32]):''}</p><span class="small">Ellenőrzés: ${date(x[15])} · Érvényesség: ${x[13]?date(x[13]):'nem ismert'}</span>${link(x[16])}</article>`).join('')}</div>`}function future(){return `${title('KÖZÖS KÖVETKEZŐ LÉPÉSEK','Mi van meg, mi jöhet még?','A felület most a kutatás első, bővíthető pillanatképét mutatja.')}<div class="future-grid section"><div><div class="eyebrow">MOST</div><h3>Amit már megnézhettek</h3><ul><li>Éttermek és kutatási állapotuk</li><li>Feldolgozott fogások, árak és források</li><li>Kétfogásos ebédmenük árai</li></ul></div><div><div class="eyebrow">KÖVETKEZŐ KÖR</div><h3>Amit együtt választunk ki</h3><ul><li>A legfontosabb éttermek hiányzó étlapjai</li><li>Régebbi és bizonytalan árak ellenőrzése</li><li>Értékelésekből kirajzolódó témák</li></ul></div><div><div class="eyebrow">KÉSŐBB</div><h3>Amivé fejlődhet</h3><ul><li>Kérdezhető kutatási asszisztens</li><li>Saját étlap és fedezet elemzése</li><li>Kiszállítási és konyhai kapacitáskalkulátor</li></ul></div></div><section class="section"><div class="eyebrow">TERVEZETT FUNKCIÓ</div><h2>Ilyeneket kérdezhetnétek</h2><p class="subtitle">A későbbi változatban a kutatás adatai alapján itt is lehetne kérdezni. Beépített chat még nem működik.</p><div class="banner">„Milyen vegetáriánus főételeket találtunk?”<br>„Milyen árakon kínálnak kétfogásos ebédmenüt?”<br>„Mely fontos éttermek étlapját nem dolgoztuk még fel?”</div></section><section class="section"><h2>Korábbi kutatás: pizzériák</h2><p class="subtitle">Az Elefántban nem lesz pizza, ezért ez külön háttéranyagként szerepel.</p><div class="cards">${pizza.map(p=>`<article class="card"><h3>${esc(p[1])}</h3><p>${esc(p[2])} · ${esc(p[4]||'')}</p><p>${esc(p[7]||'Ellenőrizendő')}</p>${link(p[6])}</article>`).join('')}</div></section>`}function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#app').innerHTML=({home,places:placelist,foods:foodlist,prices,future}[page])();document.querySelectorAll('.toolbar input,.toolbar select').forEach(el=>{let ev=el.tagName==='INPUT'?'input':'change';el.addEventListener(ev,e=>{let id=e.target.id,pos=e.target.selectionStart;filters[id]=e.target.value;render();let next=document.getElementById(id);if(next&&el.tagName==='INPUT'){next.focus();if(next.type!=='number'&&pos!=null)next.setSelectionRange(pos,pos)}})})}document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{filters={};go(b.dataset.page)});Promise.all([0,1,2,3].map(i=>fetch('data'+i+'.json').then(r=>{if(!r.ok)throw Error();return r.json()}))).then(a=>{places=a[0].slice(1).filter(x=>x[0]);foods=a[1].slice(1);lunch=a[2].slice(1).filter(x=>x[0]);pizza=a[3].slice(1).filter(x=>x[0]);render()}).catch(()=>{$('#app').innerHTML='<div class="note">Az adatokat nem sikerült betölteni. Ellenőrizzétek a kapcsolatot és próbáljátok újra.</div>'});
